import AppKit

/// Polls the system pasteboard conservatively when `clipboardHistoryEnabled` is active, ignoring
/// password-manager concealed/transient items.
@MainActor
final class ClipboardMonitor {
    static let shared = ClipboardMonitor()

    private static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]

    private var lastChangeCount = NSPasteboard.general.changeCount
    private var monitorTask: Task<Void, Never>?

    func start() {
        guard monitorTask == nil else { return }
        lastChangeCount = NSPasteboard.general.changeCount
        monitorTask = Task { @MainActor [weak self] in
            while !Task.isCancelled {
                try? await Task.sleep(for: .milliseconds(1200), tolerance: .milliseconds(300))
                guard !Task.isCancelled else { break }
                self?.checkPasteboard()
            }
        }
    }

    func checkPasteboard() {
        let pasteboard = NSPasteboard.general
        let currentCount = pasteboard.changeCount
        guard currentCount != lastChangeCount else { return }
        lastChangeCount = currentCount
        guard SettingsStore.shared.clipboardHistoryEnabled else { return }

        if let types = pasteboard.types {
            for type in types where Self.ignoredTypes.contains(type.rawValue) {
                notifySkippedSecretIfNeeded()
                return
            }
        }
        guard let text = pasteboard.string(forType: .string), !text.isEmpty else { return }
        guard !Self.looksLikeSecret(text) else {
            notifySkippedSecretIfNeeded()
            return
        }
        if SettingsStore.shared.recordClipboard(text),
           SettingsStore.shared.clipboardCopyToast,
           SettingsStore.shared.overlayPlacement == .notchIsland {
            DynamicIslandPanel.showCopied(preview: text)
        }
    }

    private func notifySkippedSecretIfNeeded() {
        let settings = SettingsStore.shared
        guard settings.clipboardHistoryEnabled,
              settings.clipboardCopyToast,
              settings.overlayPlacement == .notchIsland else { return }
        DynamicIslandPanel.showSkippedSecret()
    }

    /// Lightweight zero-regex filter that skips obvious credentials, API tokens, and private keys
    /// even when copied from apps that do not tag `ConcealedType`.
    private static func looksLikeSecret(_ text: String) -> Bool {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, trimmed.count <= 4096 else { return false }
        if trimmed.hasPrefix("-----BEGIN ") && trimmed.contains("PRIVATE KEY") { return true }
        let singleLine = !trimmed.contains(where: \.isNewline) && !trimmed.contains(" ")
        guard singleLine else { return false }
        let upper = trimmed.uppercased()
        if upper.hasSuffix("_SECRET") || upper.hasSuffix("_TOKEN") || upper.hasSuffix("_PASSWORD") || upper.hasSuffix("_API_KEY") {
            return true
        }
        if upper.contains("SECRETKEY") || upper.contains("API_SECRET") || upper.contains("ACCESS_TOKEN") {
            return true
        }
        let secretPrefixes = ["sk-", "sk_live_", "sk_test_", "ghp_", "gho_", "ghu_", "ghs_", "github_pat_", "AIza", "AKIA", "xoxb-", "xoxp-"]
        if secretPrefixes.contains(where: { trimmed.hasPrefix($0) }) && trimmed.count >= 20 {
            return true
        }
        return false
    }

    static func copyToPasteboard(_ text: String) {
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        pasteboard.setString(text, forType: .string)
        shared.lastChangeCount = pasteboard.changeCount
    }
}
